package com.frerox.toolz.data.browser.adblock
object RuleParser{
    fun cleanRule(rule: String): String?{ var c=rule.trim().lowercase(); if(c.isEmpty()) return null; if(c.contains("##")||c.contains("#?#")||c.contains("#@#")||c.contains("#\$#")) return null; if(c.startsWith("@@")) c=c.substring(2); if(c.startsWith("||")) c=c.substring(2) else if(c.startsWith("|")) c=c.substring(1); if(c.startsWith("http://")) c=c.substring(7) else if(c.startsWith("https://")) c=c.substring(8); if(c.startsWith("||")) c=c.substring(2); if(c.contains("$")) c=c.substringBefore("$"); if(c.contains("^")) c=c.substringBefore("^"); if(c.endsWith("|")) c=c.dropLast(1); if(c.endsWith("/")&&!c.dropLast(1).contains("/")) c=c.removeSuffix("/"); return c.trim().takeIf{ it.isNotBlank()} }
    fun isSafeNetworkPattern(cleaned:String):Boolean{ val l=cleaned.lowercase().trim(); val unsafe=setOf("*.css","*.js","*.png","*.jpg","*.jpeg","*.gif","*.svg","*.woff","*.woff2","*.ttf","*.eot","*.ico","*.json","/*.css","/*.js","css","js","png"); if(unsafe.contains(l)) return false; if(l.startsWith("*.")||l.startsWith("/*.")||(l.startsWith("*")&&!l.contains("/"))){ val ext=l.substringAfterLast("."); if(ext in setOf("css","js","png","jpg","jpeg","gif","svg","woff","woff2")){ val hasAd=l.contains("ad")||l.contains("track")||l.contains("pixel")||l.contains("analytics"); if(!hasAd) return false } } ; return true }
    fun isHostsLine(line:String):Boolean= line.startsWith("0.0.0.0")||line.startsWith("127.0.0.1")||line.startsWith("::1")||line.startsWith("::")
    fun indexOfComment(line:String):Int{ val h=line.indexOf('#'); val e=line.indexOf('!'); val cand=listOf(h,e).filter{it>0}; return cand.minOrNull()?:-1}
    fun parseBlocklistText(text:String): Set<String>{ val rules=mutableSetOf<String>(); text.lineSequence().forEach{ line-> var t=line.trim(); if(t.isEmpty()||t.startsWith("#")||t.startsWith("!")||t.startsWith("[")||t.startsWith(";")) return@forEach; if(t.contains("##")||t.contains("#@#")||t.contains("#?#")||t.contains("#\$#")) return@forEach; val idx=indexOfComment(t); if(idx!=-1) t=t.substring(0, idx).trim(); if(t.isEmpty()) return@forEach; if(isHostsLine(t)){ val parts=t.split(Regex("\\s+")); for(i in 1 until parts.size){ val d=parts[i].lowercase().trim(); if(d.contains(".") && d!="localhost" && d!="broadcasthost" && !d.startsWith("#")) rules.add(d) } } else rules.add(t) }; return rules }
}
